<template>
  <div class="kit-modal" role="dialog" aria-modal="true" :aria-label="isEditing?'키트 수정':'키트 등록'" @keydown.esc="emit('close')">
    <button class="modal-backdrop" aria-label="닫기" @click="emit('close')"></button>
    <div class="modal-panel">
      <header><div><small>{{ isEditing?'EDIT KIT':'NEW KIT' }}</small><h2>{{ isEditing?'키트 수정':'새 키트 등록' }}</h2><p>기본 정보와 구성 상품을 확인한 후 저장하세요.</p></div><button class="modal-close" aria-label="닫기" @click="emit('close')"><i class="fa-solid fa-xmark"></i></button></header>
      <div class="modal-body">
        <section class="kit-info"><h3>기본 정보</h3><label><span>키트 이름 *</span><input v-model.trim="form.kitName" placeholder="키트 이름"></label><label><span>설명</span><textarea v-model.trim="form.description" rows="3" placeholder="키트의 특징을 입력하세요."></textarea></label><div class="field-pair"><label><span>목록 이미지 경로</span><input v-model.trim="form.imagePath" placeholder="/img/kit.png"></label><label><span>상세 이미지 경로</span><input v-model.trim="form.detailImage" placeholder="/img/kit_detail.png"></label></div><label><span>키트 판매가 *</span><input v-model.number="form.price" type="number" min="0"></label><div class="price-summary"><span>구성 상품 정상가</span><strong>{{ formatPrice(originalPrice) }}</strong><em v-if="savingAmount>0">{{ formatPrice(savingAmount) }} 할인</em></div></section>
        <section class="product-picker"><div class="section-head"><div><h3>상품 선택</h3><span>{{ products.length }}개 상품</span></div><input v-model.trim="keyword" type="search" placeholder="상품명 검색"></div><div v-if="loading" class="picker-empty">상품을 불러오는 중입니다.</div><div v-else-if="!filteredProducts.length" class="picker-empty">검색 결과가 없습니다.</div><div v-else class="picker-list"><article v-for="product in filteredProducts" :key="product._id"><img :src="product.imagePath||fallbackImage" :alt="product.koreanName"><div><strong>{{ product.koreanName }}</strong><span>{{ formatPrice(product.consumerPrice) }} · 재고 {{ product.stock||0 }}개</span></div><input v-model.number="quantities[product._id]" type="number" min="1" :max="Math.max(1,product.stock||1)" :aria-label="`${product.koreanName} 수량`"><button :disabled="isSelected(product._id)||Number(product.stock)<=0" @click="addToKit(product)">{{ isSelected(product._id)?'추가됨':'추가' }}</button></article></div></section>
        <section class="selected-products"><div class="section-head"><div><h3>키트 구성</h3><span>{{ selectedProducts.length }}종</span></div></div><div v-if="!selectedProducts.length" class="picker-empty"><i class="fa-solid fa-box-open"></i><span>구성 상품을 추가해 주세요.</span></div><div v-else class="selected-list"><article v-for="item in selectedProducts" :key="item._id"><div><strong>{{ item.koreanName }}</strong><span>{{ formatPrice(item.consumerPrice) }}</span></div><label><input v-model.number="item.quantity" type="number" min="1" :max="Math.max(1,item.stock||1)" @change="normalizeQuantity(item)">개</label><button aria-label="구성에서 제거" @click="removeFromKit(item._id)"><i class="fa-solid fa-xmark"></i></button></article></div></section>
      </div>
      <footer><button class="admin-btn ghost" @click="emit('close')">취소</button><button class="admin-btn primary" :disabled="saving" @click="submitKit">{{ saving?'저장 중':isEditing?'수정 내용 저장':'키트 등록' }}</button></footer>
    </div>
  </div>
</template>
<script setup>
import { computed,onMounted,reactive,ref,watch } from "vue";import AdminService from "@/api/AdminService";import { getStoredToken } from "@/utils/storage";
const props=defineProps({editTarget:{type:Object,default:null}}),emit=defineEmits(["close","created"]),fallbackImage="/img/defalut_product.png";
const products=ref([]),selectedProducts=ref([]),quantities=ref({}),keyword=ref(""),loading=ref(false),saving=ref(false);const form=reactive({kitName:"",description:"",imagePath:"",detailImage:"",price:0});const isEditing=computed(()=>Boolean(props.editTarget));const filteredProducts=computed(()=>products.value.filter(p=>[p.koreanName,p.productName].some(v=>String(v||"").toLowerCase().includes(keyword.value.toLowerCase()))));const originalPrice=computed(()=>selectedProducts.value.reduce((sum,item)=>sum+Number(item.consumerPrice||0)*Number(item.quantity||0),0));const savingAmount=computed(()=>Math.max(0,originalPrice.value-Number(form.price||0)));const formatPrice=value=>`${Number(value||0).toLocaleString("ko-KR")}원`;const isSelected=id=>selectedProducts.value.some(item=>item._id===id);
async function fetchProducts(){loading.value=true;try{const{data}=await AdminService.getAllProducts(getStoredToken());products.value=Array.isArray(data)?data:[]}catch(err){console.error("키트 구성 상품 조회 실패:",err)}finally{loading.value=false}}
function addToKit(product){if(isSelected(product._id)||Number(product.stock)<=0)return;selectedProducts.value.push({...product,quantity:Math.max(1,Number(quantities.value[product._id]||1))})}function removeFromKit(id){selectedProducts.value=selectedProducts.value.filter(item=>item._id!==id)}function normalizeQuantity(item){item.quantity=Math.min(Math.max(1,Number(item.quantity)||1),Math.max(1,Number(item.stock)||1))}
async function submitKit(){if(!form.kitName)return alert("키트 이름을 입력해 주세요.");if(!selectedProducts.value.length)return alert("구성 상품을 하나 이상 추가해 주세요.");if(Number(form.price)<=0)return alert("키트 판매가를 입력해 주세요.");if(selectedProducts.value.some(item=>Number(item.quantity)>Number(item.stock)))return alert("구성 수량이 상품 재고보다 많습니다.");const payload={...form,price:Number(form.price),originalPrice:originalPrice.value,products:selectedProducts.value.map(item=>({productId:item._id,quantity:Number(item.quantity) }))};saving.value=true;try{isEditing.value?await AdminService.updateKit(props.editTarget._id,payload,getStoredToken()):await AdminService.createKit(payload,getStoredToken());alert(isEditing.value?"키트가 수정되었습니다.":"키트가 등록되었습니다.");emit("created")}catch(err){console.error("키트 저장 실패:",err);alert(err.response?.data?.message||"키트를 저장하지 못했습니다.")}finally{saving.value=false}}
watch(()=>props.editTarget,kit=>{Object.assign(form,{kitName:kit?.kitName||"",description:kit?.description||"",imagePath:kit?.imagePath||"",detailImage:kit?.detailImage||"",price:Number(kit?.price||0)});selectedProducts.value=(kit?.products||[]).filter(item=>item.productId).map(item=>({...item.productId,quantity:Number(item.quantity||1)}))},{immediate:true});onMounted(fetchProducts);
</script>
<style scoped>
.kit-modal{position:fixed;inset:0;z-index:2000;display:grid;place-items:center;padding:22px}.modal-backdrop{position:absolute;inset:0;width:100%;height:100%;border:0;background:rgba(30,23,27,.58);backdrop-filter:blur(3px)}.modal-panel{position:relative;width:min(1180px,100%);max-height:calc(100vh - 44px);display:flex;flex-direction:column;background:#fff;box-shadow:0 24px 80px rgba(20,14,17,.28)}header{display:flex;justify-content:space-between;padding:22px 24px 18px;border-bottom:1px solid #e8e0dd}header small{color:#aa7c87;font-size:.58rem;font-weight:800;letter-spacing:.18em}header h2{margin:4px 0;font-family:Georgia,"Noto Serif KR",serif;font-size:1.45rem;font-weight:400}header p{margin:0;color:#91868a;font-size:.67rem}.modal-close{width:38px;height:38px;border:1px solid #e2dad7;background:#fff;cursor:pointer}.modal-body{display:grid;grid-template-columns:1fr 1.15fr .85fr;gap:18px;padding:20px 24px;overflow:auto}.modal-body section{min-width:0}.modal-body h3{margin:0 0 14px;font-size:.82rem}.kit-info,.kit-info label{display:grid;gap:7px}.kit-info{align-content:start;gap:12px}.kit-info label span{color:#71666b;font-size:.64rem;font-weight:700}.kit-info input,.kit-info textarea,.section-head input{padding:10px;border:1px solid #ddd4d1;outline:none;font:inherit;font-size:.7rem;resize:vertical}.field-pair{display:grid;grid-template-columns:1fr 1fr;gap:8px}.price-summary{display:flex;align-items:center;gap:8px;padding:14px;background:#f6f1f2;font-size:.66rem}.price-summary strong{margin-left:auto;font-size:.85rem}.price-summary em{color:#a05563;font-size:.61rem;font-style:normal}.section-head{display:flex;justify-content:space-between;align-items:start;gap:8px;margin-bottom:12px}.section-head h3{margin:0}.section-head span{color:#9a9094;font-size:.62rem}.section-head input{width:145px;padding:7px}.picker-list,.selected-list{max-height:490px;display:grid;gap:7px;overflow:auto}.picker-list article,.selected-list article{display:flex;align-items:center;gap:8px;padding:8px;border:1px solid #ebe4e1}.picker-list img{width:42px;height:48px;object-fit:contain;background:#f6f3f1}.picker-list article>div,.selected-list article>div{min-width:0;display:grid;flex:1;gap:3px}.picker-list strong,.selected-list strong{overflow:hidden;font-size:.66rem;text-overflow:ellipsis;white-space:nowrap}.picker-list span,.selected-list span{color:#958a8e;font-size:.58rem}.picker-list input,.selected-list input{width:48px;padding:6px;border:1px solid #ddd4d1}.picker-list button{height:31px;padding:0 9px;border:1px solid #d7cccf;color:#684c59;background:#fff;font-size:.62rem;cursor:pointer}.picker-list button:disabled{opacity:.45}.selected-list label{display:flex;align-items:center;gap:3px;font-size:.6rem}.selected-list button{border:0;color:#aa6b70;background:transparent;cursor:pointer}.picker-empty{min-height:130px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;color:#9b9194;font-size:.67rem;background:#faf8f7}footer{display:flex;justify-content:flex-end;gap:8px;padding:15px 24px;border-top:1px solid #e8e0dd}@media(max-width:900px){.modal-body{grid-template-columns:1fr}.picker-list,.selected-list{max-height:300px}}@media(max-width:520px){.kit-modal{padding:0}.modal-panel{max-height:100vh}.modal-body,header{padding-inline:15px}.field-pair{grid-template-columns:1fr}footer .admin-btn{flex:1}}
</style>
